const tiers = (top = 12) => [
  { minQty: 1, discountPct: 0 },
  { minQty: 5, discountPct: 5 },
  { minQty: 10, discountPct: top },
];

function p(row) {
  const { top, ...rest } = row;
  return {
    alsoIn: [],
    packs: [],
    bulkTiers: tiers(top ?? 12),
    stock: "in",
    tags: [],
    ...rest,
  };
}

